/**
 * Radio or checkbox options as cards with room for a description (`design/components/choice-card.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/choice-card.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  Icon,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  roveRadio,
  scope,
  type Defaults,
  type IconRole,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/choice-card.module.css'

export interface ChoiceCardOption {
  value: string
  label: string
  description?: string
  icon?: IconRole
  disabled?: boolean
}

export interface ChoiceCardProps {
  /**
   * The maximum column count. The container resolves the actual count on Grid's scale
   * (`grid.md`).
   */
  columns?: 1 | 2 | 3
  defaultValue?: string | string[]
  disabled?: boolean
  /**
   * The group's accessible name (`aria-label` on the root).
   */
  label: string
  mode: 'single' | 'multiple'
  onChange?: ((value: string) => void) | ((values: string[]) => void)
  /**
   * Items render from data (Radio's law).
   */
  options: ChoiceCardOption[]
  value?: string | string[]
}

/** Radio or checkbox options as cards with room for a description. */
export default function ChoiceCard(given: ChoiceCardProps): JSX.Element {
  const props = mergeProps(
    { columns: 1, disabled: false } as Defaults<ChoiceCardProps, 'columns' | 'disabled'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const grid = elementRef<HTMLElement>()
    const singleMirror = createCell(
      props.mode === 'single' ? (props.defaultValue as string | undefined) : undefined,
    )
    const multipleMirror = createCell(
      props.mode === 'multiple' ? ((props.defaultValue as string[] | undefined) ?? []) : [],
    )
    const chosen = createDerived(() =>
      props.mode === 'single'
        ? ((props.value as string | undefined) ?? singleMirror.value)
        : undefined,
    )
    const checkedValues = createDerived(() =>
      props.mode === 'multiple'
        ? ((props.value as string[] | undefined) ?? multipleMirror.value)
        : ([] as string[]),
    )
    const isChecked = createDerived(
      () => (optionValue: string) =>
        props.mode === 'single'
          ? chosen.value === optionValue
          : checkedValues.value.includes(optionValue),
    )
    const stop = createDerived(
      () =>
        chosen.value ??
        props.options.find((option) => !(props.disabled || option.disabled === true))?.value,
    )
    const select = createDerived(
      () => (next: string) =>
        next !== chosen.value &&
        ((singleMirror.value = next),
        (props.onChange as unknown as ((...args: unknown[]) => unknown) | undefined)?.(next),
        true),
    )
    const toggle = createDerived(
      () => (optionValue: string, checked: boolean) =>
        ((next: string[]) => (
          (multipleMirror.value = next),
          (props.onChange as unknown as ((...args: unknown[]) => unknown) | undefined)?.(next)
        ))(
          props.options
            .filter((option) =>
              option.value === optionValue ? checked : checkedValues.value.includes(option.value),
            )
            .map((option) => option.value),
        ),
    )
    const chooseAll = createDerived(
      () => (chosen: readonly string[]) =>
        ((next: string[]) =>
          next.length === checkedValues.value.length &&
          next.every((each) => checkedValues.value.includes(each))
            ? undefined
            : ((multipleMirror.value = next),
              (props.onChange as unknown as ((...args: unknown[]) => unknown) | undefined)?.(
                next,
              )))(
          props.options
            .filter((option) =>
              props.disabled || option.disabled === true
                ? checkedValues.value.includes(option.value)
                : chosen.includes(option.value),
            )
            .map((option) => option.value),
        ),
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'ChoiceCard',
        element: () => grid.value,
        state: () => ({
          value:
            props.mode === 'single'
              ? chosen.value === undefined
                ? []
                : [chosen.value]
              : checkedValues.value,
          options: props.options.map((option) => ({
            id: option.value,
            label: option.label,
            ...(option.disabled === true ? { disabled: true } : {}),
          })),
          mode: props.mode,
          disabled: props.disabled,
        }),
        actions: {
          choose: {
            argument: 'ids',
            run: (value) =>
              (() => {
                if (props.mode === 'multiple') return chooseAll.value(value)
                const [only] = value
                if (only === undefined || value.length !== 1)
                  throw new Error('A single-choice ChoiceCard takes exactly one id.')
                select.value(only)
              })(),
          },
        },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <>
        {props.mode === 'single' ? (
          <div
            class={styles.grid}
            role="radiogroup"
            aria-label={props.label}
            data-columns={String(props.columns)}
            data-disabled={props.disabled ? '' : undefined}
            data-member="choice-card"
            ref={grid.attach}
          >
            <Each of={props.options} by={(option) => option.value} renew>
              {(option, index) => (
                <label
                  class={styles.option}
                  data-state={isChecked.value(option.value) ? 'checked' : 'unchecked'}
                  data-disabled={props.disabled || option.disabled === true ? '' : undefined}
                >
                  {/* card */}
                  <button
                    class={styles.control}
                    type="button"
                    role="radio"
                    value={option.value}
                    aria-checked={isChecked.value(option.value)}
                    disabled={props.disabled || option.disabled === true}
                    aria-labelledby={`${uid}-option-${index()}-label`}
                    aria-describedby={
                      option.description !== undefined
                        ? `${uid}-option-${index()}-description`
                        : undefined
                    }
                    data-state={isChecked.value(option.value) ? 'checked' : 'unchecked'}
                    data-disabled={props.disabled || option.disabled === true ? '' : undefined}
                    tabindex={option.value === stop.value ? 0 : -1}
                    onclick={() => select.value(option.value)}
                    onkeydown={($event: KeyboardEvent) =>
                      $event.key === 'Enter'
                        ? $event.preventDefault()
                        : roveRadio($event, (next) => select.value(next))
                    }
                  />
                  {option.icon !== undefined ? (
                    <span class={styles.icon}>
                      <Icon name={option.icon} size="md" />
                    </span>
                  ) : null}
                  <span class={styles.label} id={`${uid}-option-${index()}-label`}>
                    {option.label}
                  </span>
                  {option.description !== undefined ? (
                    <span class={styles.description} id={`${uid}-option-${index()}-description`}>
                      {option.description}
                    </span>
                  ) : null}
                  {isChecked.value(option.value) ? (
                    <span class={styles.glyph}>
                      <Icon name="confirm" size="md" />
                    </span>
                  ) : null}
                </label>
              )}
            </Each>
          </div>
        ) : (
          <div
            class={styles.grid}
            role="group"
            aria-label={props.label}
            data-columns={String(props.columns)}
            data-disabled={props.disabled ? '' : undefined}
            data-member="choice-card"
            ref={grid.attach}
          >
            <Each of={props.options} by={(option) => option.value} renew>
              {(option, index) => (
                <label
                  class={styles.option}
                  data-state={isChecked.value(option.value) ? 'checked' : 'unchecked'}
                  data-disabled={props.disabled || option.disabled === true ? '' : undefined}
                >
                  {/* card */}
                  <button
                    class={styles.control}
                    type="button"
                    role="checkbox"
                    value={option.value}
                    aria-checked={isChecked.value(option.value)}
                    disabled={props.disabled || option.disabled === true}
                    aria-labelledby={`${uid}-option-${index()}-label`}
                    aria-describedby={
                      option.description !== undefined
                        ? `${uid}-option-${index()}-description`
                        : undefined
                    }
                    data-state={isChecked.value(option.value) ? 'checked' : 'unchecked'}
                    data-disabled={props.disabled || option.disabled === true ? '' : undefined}
                    onclick={() => toggle.value(option.value, !isChecked.value(option.value))}
                    onkeydown={($event: KeyboardEvent) =>
                      $event.key === 'Enter' && $event.preventDefault()
                    }
                  />
                  {option.icon !== undefined ? (
                    <span class={styles.icon}>
                      <Icon name={option.icon} size="md" />
                    </span>
                  ) : null}
                  <span class={styles.label} id={`${uid}-option-${index()}-label`}>
                    {option.label}
                  </span>
                  {option.description !== undefined ? (
                    <span class={styles.description} id={`${uid}-option-${index()}-description`}>
                      {option.description}
                    </span>
                  ) : null}
                  {isChecked.value(option.value) ? (
                    <span class={styles.glyph}>
                      <Icon name="confirm" size="md" />
                    </span>
                  ) : null}
                </label>
              )}
            </Each>
          </div>
        )}
      </>
    )
  })
}
